import { BrowserRouter, Routes, Route, NavLink } from 'react-router-dom';
import { Leaf, Clock, Moon, Sun } from 'lucide-react';
import { useState, useEffect, createContext, useContext } from 'react';
import Recommend from './pages/Recommend';
import BestTime from './pages/BestTime';

// Create theme context to share theme state throughout the app
export const ThemeContext = createContext({
  isDarkMode: false,
  toggleTheme: () => {}
});

function App() {
  // Theme state management
  const [isDarkMode, setIsDarkMode] = useState(() => {
    const savedTheme = localStorage.getItem('theme');
    // Check saved preference or use system preference as default
    return savedTheme ? savedTheme === 'dark' : window.matchMedia('(prefers-color-scheme: dark)').matches;
  });

  // Update the DOM and localStorage when theme changes
  useEffect(() => {
    document.documentElement.classList.toggle('dark', isDarkMode);
    localStorage.setItem('theme', isDarkMode ? 'dark' : 'light');
  }, [isDarkMode]);

  // Toggle theme function
  const toggleTheme = () => setIsDarkMode(!isDarkMode);

  // Theme context value
  const themeContextValue = { isDarkMode, toggleTheme };

  return (
    <ThemeContext.Provider value={themeContextValue}>
      <BrowserRouter>
        <div className={`min-h-screen transition-colors duration-200 
          ${isDarkMode ? 'bg-gray-900 text-gray-100' : 'bg-gray-50 text-gray-800'}`}>

          <header className={`${isDarkMode ? 'bg-green-800' : 'bg-green-600'} shadow-md transition-colors duration-200`}>
            <div className="container mx-auto px-4">
              <nav className="flex justify-between items-center py-4">
                <div className="flex items-center space-x-2">
                  <Leaf className="text-white" size={24} />
                  <h1 className="text-2xl font-bold text-white tracking-tight">PlantSmart</h1>
                </div>

                <div className="flex items-center space-x-6">
                  <NavLink 
                    to="/" 
                    className={({ isActive }) => 
                      `flex items-center space-x-1 px-3 py-2 rounded-md transition-colors
                       ${isActive 
                         ? isDarkMode ? 'bg-green-900 text-white' : 'bg-green-700 text-white' 
                         : 'text-green-100 hover:bg-opacity-50 hover:bg-green-700'}`
                    }
                    end
                  >
                    <Leaf size={18} />
                    <span>Recommend Crop</span>
                  </NavLink>

                  <NavLink 
                    to="/best-time" 
                    className={({ isActive }) => 
                      `flex items-center space-x-1 px-3 py-2 rounded-md transition-colors
                       ${isActive 
                         ? isDarkMode ? 'bg-green-900 text-white' : 'bg-green-700 text-white' 
                         : 'text-green-100 hover:bg-opacity-50 hover:bg-green-700'}`
                    }
                  >
                    <Clock size={18} />
                    <span>Best Time</span>
                  </NavLink>

                  <button 
                    onClick={toggleTheme}
                    className={`p-2 rounded-full transition-colors
                      ${isDarkMode 
                        ? 'bg-green-900 text-yellow-200 hover:bg-green-950' 
                        : 'bg-green-700 text-yellow-100 hover:bg-green-800'}`}
                    aria-label={isDarkMode ? "Switch to light mode" : "Switch to dark mode"}
                    title={isDarkMode ? "Switch to light mode" : "Switch to dark mode"}
                  >
                    {isDarkMode ? <Sun size={18} /> : <Moon size={18} />}
                  </button>
                </div>
              </nav>
            </div>
          </header>

          <main className={`flex-grow container mx-auto px-4 py-8 transition-colors duration-200
            ${isDarkMode ? 'bg-gray-900' : 'bg-gray-50'}`}>
            <Routes>
              <Route path="/" element={<Recommend />} />
              <Route path="/best-time" element={<BestTime />} />
            </Routes>
          </main>

          <footer className={`transition-colors duration-200 py-4
            ${isDarkMode ? 'bg-green-800 text-gray-200' : 'bg-green-600 text-white'}`}>
            <div className="container mx-auto px-4 text-center text-sm">
              © {new Date().getFullYear()} PlantSmart - Smart agricultural solutions
            </div>
          </footer>
        </div>
      </BrowserRouter>
    </ThemeContext.Provider>
  );
}

// Custom hook for easy theme access in child components
export function useTheme() {
  return useContext(ThemeContext);
}

// Example of how your form components should be styled
// This is a sample form component that would be used in your pages
export function ThemedForm({ children, onSubmit }) {
  const { isDarkMode } = useTheme();

  return (
    <form 
      onSubmit={onSubmit} 
      className="space-y-4 p-6 rounded-lg shadow-md transition-colors duration-200 
        bg-white dark:bg-gray-800 border dark:border-gray-700"
    >
      {children}
    </form>
  );
}

// Example of how input fields should be styled for both themes
export function ThemedInput({ label, type = "text", name, value, onChange, required }) {
  const { isDarkMode } = useTheme();

  return (
    <div className="flex flex-col">
      <label 
        htmlFor={name} 
        className="mb-1 font-medium text-gray-700 dark:text-gray-200"
      >
        {label}
      </label>
      <input
        type={type}
        id={name}
        name={name}
        value={value}
        onChange={onChange}
        required={required}
        className="px-3 py-2 rounded border transition-colors duration-200
          bg-white dark:bg-gray-700
          text-gray-900 dark:text-white
          border-gray-300 dark:border-gray-600
          focus:outline-none focus:ring-2 focus:ring-green-500 dark:focus:ring-green-400
          focus:border-green-500 dark:focus:border-green-400"
      />
    </div>
  );
}

// Example for select inputs
export function ThemedSelect({ label, name, value, onChange, options, required }) {
  const { isDarkMode } = useTheme();

  return (
    <div className="flex flex-col">
      <label 
        htmlFor={name} 
        className="mb-1 font-medium text-gray-700 dark:text-gray-200"
      >
        {label}
      </label>
      <select
        id={name}
        name={name}
        value={value}
        onChange={onChange}
        required={required}
        className="px-3 py-2 rounded border transition-colors duration-200
          bg-white dark:bg-gray-700
          text-gray-900 dark:text-white
          border-gray-300 dark:border-gray-600
          focus:outline-none focus:ring-2 focus:ring-green-500 dark:focus:ring-green-400
          focus:border-green-500 dark:focus:border-green-400"
      >
        {options.map(option => (
          <option key={option.value} value={option.value}>
            {option.label}
          </option>
        ))}
      </select>
    </div>
  );
}

export default App;
